      partner.enemyVehicleClaim.seat=0;
      partner.enemyVehicleClaim.phase='riding';
      window.HUNTER_ENEMY_CREW_VISUAL?.show(vehicle,1,false);
      window.HUNTER_ENEMY_CREW_VISUAL?.show(vehicle,0,true);
