    const directStarted=performanceStatsVisible?performance.now():0;
    const longDistance=Math.hypot(tx-u.x,tz-u.z),
      lookahead=Math.min(1,ENEMY_DIRECT_LOOKAHEAD/Math.max(.001,longDistance));
