    const coordinates=record.kind==='walls'?['x0','x1','y0','y1','z0','z1']:record.kind==='bomb'?['x','y','z']:['x','z'];
    if(!coordinates.every(k=>Number.isFinite(record.state[k])))throw new Error('Coordenades d’entitat invàlides.');
